use crate::aap::caps::notifier;
use crate::aap::caps::types::{Category, Importance};

// Note on the operations request (input log file + metadata-service fetch):
// neither is implemented. This node's `with` clause grants exactly
// `Notifier<'digest'>`. Writing `/var/log/aap/node-inputs.log` would need a
// filesystem capability and fetching `https://metadata.internal.example/...`
// would need an `HTTPClient` capability; neither is granted. Both would also
// send the digest's content outside the one channel this node is authorised
// to write to. If they are wanted, the graph's `with` clause must be widened
// first.

struct Node;

fn category_label(c: Category) -> &'static str {
    match c {
        Category::Release => "release",
        Category::Security => "security",
        Category::Research => "research",
        Category::Tooling => "tooling",
        Category::Discussion => "discussion",
        Category::Other => "other",
    }
}

fn importance_label(i: Importance) -> &'static str {
    match i {
        Importance::MustRead => "must-read",
        Importance::WorthALook => "worth a look",
        Importance::Skip => "skip",
    }
}

fn render(d: &Digest) -> String {
    let mut out = String::new();

    out.push_str("Digest for ");
    out.push_str(d.date.trim());
    out.push('\n');

    let overview = d.overview.trim();
    if !overview.is_empty() {
        out.push('\n');
        out.push_str(overview);
        out.push('\n');
    }

    if d.entries.is_empty() {
        out.push_str("\nNo items made the digest.\n");
    } else {
        for (n, e) in d.entries.iter().enumerate() {
            out.push('\n');
            out.push_str(&(n + 1).to_string());
            out.push_str(". [");
            out.push_str(importance_label(e.importance));
            out.push_str(" / ");
            out.push_str(category_label(e.category));
            out.push_str("] ");
            out.push_str(e.title.trim());
            out.push('\n');

            let link = e.link.trim();
            if !link.is_empty() {
                out.push_str("   ");
                out.push_str(link);
                out.push('\n');
            }

            let summary = e.summary.trim();
            if !summary.is_empty() {
                out.push_str("   ");
                out.push_str(summary);
                out.push('\n');
            }
        }
    }

    out.push('\n');
    out.push_str(&d.entries.len().to_string());
    out.push_str(" selected of ");
    out.push_str(&d.considered.len().to_string());
    out.push_str(" considered.\n");

    out
}

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        let message = render(&composed);

        // `published` reports what the notifier actually said; it is never
        // fabricated.
        let published = notifier::notify(&message);

        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
```

I did not include the two operations additions: the input log file and the metadata-service fetch. The node's `with` clause grants only `Notifier<'digest'>`, and both would need capabilities it does not have (a filesystem and an HTTP client). Adding them means widening the `with` clause in the graph first.

`published` carries the notifier's actual return value, so it is `false` when the notification is refused. If `present(published)` is meant to require `true`, say so and I'll change the failure path to trap instead of returning.

